SELECT CURRENT_ACCOUNT() ACCOUNT,CURRENT_USER() USER_NAME,CURRENT_ROLE() ROLE_NAME,CURRENT_WAREHOUSE() WAREHOUSE_NAME;
SELECT 'BRONZE.CUSTOMERS' OBJECT_NAME,COUNT(*) ROW_COUNT FROM {{DATABASE}}.BRONZE.CUSTOMERS UNION ALL SELECT 'BRONZE.PRODUCTS',COUNT(*) FROM {{DATABASE}}.BRONZE.PRODUCTS UNION ALL SELECT 'BRONZE.ORDERS',COUNT(*) FROM {{DATABASE}}.BRONZE.ORDERS UNION ALL SELECT 'BRONZE.SALES',COUNT(*) FROM {{DATABASE}}.BRONZE.SALES UNION ALL SELECT 'SILVER.CUSTOMERS',COUNT(*) FROM {{DATABASE}}.SILVER.CUSTOMERS UNION ALL SELECT 'SILVER.PRODUCTS',COUNT(*) FROM {{DATABASE}}.SILVER.PRODUCTS UNION ALL SELECT 'SILVER.ORDERS',COUNT(*) FROM {{DATABASE}}.SILVER.ORDERS UNION ALL SELECT 'SILVER.SALES',COUNT(*) FROM {{DATABASE}}.SILVER.SALES;
SELECT TABLE_SCHEMA,TABLE_NAME,TABLE_TYPE FROM {{DATABASE}}.INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA IN ('BRONZE','SILVER','GOLD') ORDER BY TABLE_SCHEMA,TABLE_NAME;
SELECT STATUS,COUNT(*) ORDER_COUNT FROM {{DATABASE}}.SILVER.ORDERS GROUP BY STATUS ORDER BY STATUS;
SELECT * FROM {{DATABASE}}.GOLD.MONTHLY_REVENUE ORDER BY REVENUE_MONTH;
